"""Render the analyse HTML report."""

from __future__ import annotations

from pathlib import Path

from jinja2 import Environment, FileSystemLoader, StrictUndefined

from harness.analyse.aggregator import SessionAnalysis, fmt_duration
from harness.analyse.synthesis import Narrative

_TEMPLATE_DIR = Path(__file__).parent / "templates"


def render_html(
    analysis: SessionAnalysis,
    narrative: Narrative,
    *,
    auto_refresh_seconds: int | None = None,
) -> str:
    """Render the timeline HTML report.

    When `auto_refresh_seconds` is set, the template injects a
    `<meta http-equiv="refresh" content="<N>">` tag and a "live" badge so the
    browser tab reloads automatically under `harness analyse --watch`.
    """
    env = Environment(
        loader=FileSystemLoader(str(_TEMPLATE_DIR)),
        autoescape=True,
        undefined=StrictUndefined,
        trim_blocks=True,
        lstrip_blocks=True,
    )
    tmpl = env.get_template("timeline.html.j2")

    # Token totals — kept separate so cost stays accurate vs cache savings stay visible.
    # `total_tokens`  = input + output         (the work Claude actually did)
    # `cache_tokens`  = cache_read + cache_create  (the cache footprint, billed separately)
    total_tokens = (
        analysis.total_metrics.input_tokens
        + analysis.total_metrics.output_tokens
    )
    cache_tokens = (
        analysis.total_metrics.cache_create_tokens
        + analysis.total_metrics.cache_read_tokens
    )

    def _pretty(n: int) -> str:
        if n >= 1_000_000:
            return f"{n / 1_000_000:.1f}M"
        if n >= 1_000:
            return f"{n / 1_000:.1f}k"
        return str(n)

    total_tokens_pretty = _pretty(total_tokens)
    cache_tokens_pretty = _pretty(cache_tokens)

    phases_with_narrative = []
    for ph, narr in zip(analysis.phases, narrative.phases, strict=False):
        ph.duration_pretty = fmt_duration(ph.duration_seconds)  # type: ignore[attr-defined]
        phases_with_narrative.append((ph, narr))

    title = analysis.session.title or f"Session {analysis.session.session_id[:8]}"

    from datetime import datetime
    rendered_at = datetime.now().strftime("%H:%M:%S") if auto_refresh_seconds else None

    return tmpl.render(
        title=title,
        session=analysis.session,
        narrative=narrative,
        phases_with_narrative=phases_with_narrative,
        duration_pretty=fmt_duration(analysis.session.duration_seconds),
        total_tokens_pretty=total_tokens_pretty,
        cache_tokens_pretty=cache_tokens_pretty,
        cost_usd=analysis.total_cost_usd,
        totals=analysis.total_metrics,
        slash_command_count=sum(1 for ph in analysis.phases if ph.slash_command),
        subagent_total=sum(analysis.total_metrics.subagent_calls.values()),
        bash_total=analysis.total_metrics.tool_counts.get("Bash", 0),
        edit_total=(
            analysis.total_metrics.tool_counts.get("Edit", 0)
            + analysis.total_metrics.tool_counts.get("MultiEdit", 0)
        ),
        mcp_total=sum(analysis.total_metrics.mcp_calls.values()),
        auto_refresh=auto_refresh_seconds,
        rendered_at=rendered_at,
    )
